" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "TraceStep" (     "id" TEXT NOT NULL,     "traceId" TEXT NOT NULL,     "stepNumber" INTEGER NOT NULL,     "capability" TEXT NOT NULL,     "description" TEXT NOT NULL,     "status" TEXT NOT NULL,     "error" TEXT,     "result" JSONB,     "screenshotPath" TEXT,     "llmLatencyMs" INTEGER,     "executionLatencyMs" INTEGER,     "tokenUsage" INTEGER,     "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,     "completedAt" TIMESTAMP(3),      CONSTRAINT "TraceStep_pkey" PRIMARY KEY ("id") );  -- CreateTable CREATE TABLE "UserWebhook" (     "id" TEXT NOT NULL,     "userId" TEXT NOT NULL,     "name" TEXT,     "url" TEXT NOT NULL,     "events" JSONB NOT NULL,     "active" BOOLEAN NOT NULL DEFAULT true,     "headers" JSONB,     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,     "updatedAt" TIMESTAMP(3) NOT NULL,      CONSTRAINT "UserWebhook_pkey" PRIMARY KEY ("id") );  -- CreateIndex CREATE UNIQUE INDEX "User_email_key" ON "User"("email");  -- CreateIndex CREATE INDEX "UserApiKey_userId_idx" ON "UserApiKey"("userId");  -- CreateIndex CREATE UNIQUE INDEX "UserApiKey_userId_provider_key" ON "UserApiKey"("userId", "provider");  -- CreateIndex CREATE INDEX "Session_userId_createdAt_idx" ON "Session"("userId", "createdAt");  -- CreateIndex CREATE INDEX "StepLog_sessionId_stepNumber_idx" ON "StepLog"("sessionId", "stepNumber");  -- CreateIndex CREATE INDEX "Trace_userId_createdAt_idx" ON "Trace"("userId", "createdAt");  -- CreateIndex CREATE INDEX "TraceStep_traceId_stepNumber_idx" ON "TraceStep"("traceId", "stepNumber");  -- CreateIndex CREATE INDEX "UserWebhook_userId_active_idx" ON "UserWebhook"("userId", "active");  -- AddForeignKey ALTER TABLE "UserApiKey" ADD CONSTRAINT "UserApiKey_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;  -- AddForeignKey ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON